// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        address actor = address(uint160(uint256(keccak256(abi.encode(amount)))));
        vm.assume(actor != address(0));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        c.withdrawAll();

        uint256 balAfter = address(c).balance;

        assertTrue(balBefore - balAfter == amount);
    }
}
